"""Listing and creating the branches of an agent's repository.

Branches live in the repository of the agent's main workspace. Their
checkouts are managed by `rasa.builder.workspace.WorkspaceManager`.
"""

import subprocess
from pathlib import Path
from typing import List, Optional

from rasa.builder.exceptions import BranchAlreadyExistsError, BranchNotFoundError
from rasa.builder.models import BranchInfo
from rasa.builder.workspace import (
    DEFAULT_BRANCH,
    Workspace,
    branch_checkout_path,
    validate_branch_name,
)

_FIELD_SEPARATOR = "\t"
_BRANCH_FORMAT = _FIELD_SEPARATOR.join(
    [
        "%(refname:short)",
        "%(objectname)",
        "%(authorname)",
        "%(committerdate:iso8601-strict)",
    ]
)


async def list_branches(main: Workspace, root: Path) -> List[BranchInfo]:
    """Return every local branch of an agent, compared with `main`.

    Args:
        main: The agent's main workspace.
        root: The workspaces root, to tell which branches have a checkout.

    Returns:
        The agent's branches, `main` first, then by name. An agent without
        commits has no branches yet.
    """
    git_service = main.git_service
    output = await git_service.run_git_command(
        ["branch", "--list", f"--format={_BRANCH_FORMAT}"], check_output=True
    )
    branches = []
    for line in (output or "").splitlines():
        name, head_sha, author, date = line.split(_FIELD_SEPARATOR)
        ahead, behind = 0, 0
        if name != DEFAULT_BRANCH:
            ahead, behind = await _ahead_behind(main, name)
        has_checkout = (
            True
            if name == DEFAULT_BRANCH
            else branch_checkout_path(root, main.agent_id, name).is_dir()
        )
        branches.append(
            BranchInfo(
                name=name,
                head_sha=head_sha,
                ahead=ahead,
                behind=behind,
                last_commit_author=author,
                last_commit_date=date,
                has_checkout=has_checkout,
            )
        )
    branches.sort(key=lambda branch: (branch.name != DEFAULT_BRANCH, branch.name))
    return branches


async def branches_besides_main(main: Workspace) -> List[str]:
    """Return the names of an agent's branches other than `main`."""
    output = await main.git_service.run_git_command(
        ["branch", "--list", "--format=%(refname:short)"], check_output=True
    )
    return [name for name in (output or "").splitlines() if name != DEFAULT_BRANCH]


async def create_branch(
    main: Workspace, name: str, from_ref: Optional[str] = None
) -> None:
    """Create a branch in an agent's repository without checking it out.

    Args:
        main: The agent's main workspace.
        name: Name of the new branch.
        from_ref: Branch name or commit SHA to start from; `main` if `None`.

    Raises:
        InvalidBranchNameError: If `name` is not a valid branch name.
        BranchAlreadyExistsError: If the agent already has a branch `name`.
        BranchNotFoundError: If `from_ref` names no branch or commit of the
            agent, including when the agent has no commits yet.
    """
    validate_branch_name(name)
    start = from_ref or DEFAULT_BRANCH
    git_service = main.git_service

    start_sha = await _resolve_commit(main, start)
    if start_sha is None:
        raise BranchNotFoundError(
            f"Agent '{main.agent_id}' has no branch or commit '{start}'."
        )

    async with git_service.git_operation():
        if await _resolve_commit(main, f"refs/heads/{name}") is not None:
            raise BranchAlreadyExistsError(
                f"Agent '{main.agent_id}' already has a branch named '{name}'."
            )
        await git_service.run_git_command(["branch", name, start_sha])


async def _resolve_commit(main: Workspace, ref: str) -> Optional[str]:
    """Return the commit SHA `ref` points to, or `None` if it points nowhere."""
    try:
        output = await main.git_service.run_git_command(
            [
                "rev-parse",
                "--verify",
                "--quiet",
                "--end-of-options",
                f"{ref}^{{commit}}",
            ],
            check_output=True,
            skip_error_logging=True,
        )
    except subprocess.CalledProcessError:
        return None
    return (output or "").strip() or None


async def _ahead_behind(main: Workspace, branch: str) -> tuple[int, int]:
    """Return how many commits `branch` is ahead of and behind `main`."""
    output = await main.git_service.run_git_command(
        ["rev-list", "--left-right", "--count", f"{DEFAULT_BRANCH}...{branch}"],
        check_output=True,
    )
    behind, ahead = (output or "0\t0").split()
    return int(ahead), int(behind)
